import React, { useState, useEffect } from 'react';
import { profilesStorageKey } from '../userStorage';

export interface UserProfile {
  id: string;
  name: string;
  avatar: string;
}

interface UserSelectorProps {
  storageNamespace: string;
  seedProfiles?: UserProfile[];
  currentUserId: string;
  onUserChange: (userId: string) => void;
  onNewUser: (user: UserProfile) => void;
}

export const UserSelector: React.FC<UserSelectorProps> = ({
  storageNamespace,
  seedProfiles,
  currentUserId,
  onUserChange,
  onNewUser
}) => {
  const STORAGE_KEY = profilesStorageKey(storageNamespace);
  const [showNewUserForm, setShowNewUserForm] = useState(false);
  const [newUserName, setNewUserName] = useState('');
  const [users, setUsers] = useState<UserProfile[]>(() => seedProfiles ?? []);

  useEffect(() => {
    if (seedProfiles && seedProfiles.length > 0) {
      const existingRaw = localStorage.getItem(STORAGE_KEY);
      if (!existingRaw) {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(seedProfiles));
        setUsers(seedProfiles);
        return;
      }
    }
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (!stored) {
        const fallback = seedProfiles && seedProfiles.length > 0 ? seedProfiles : [];
        setUsers(fallback.length > 0 ? fallback : []);
        return;
      }
      const parsed = JSON.parse(stored) as UserProfile[];
      if (Array.isArray(parsed) && parsed.length > 0) {
        setUsers(parsed);
        return;
      }
      const fallback = seedProfiles && seedProfiles.length > 0 ? seedProfiles : [];
      setUsers(fallback.length > 0 ? fallback : []);
    } catch {
      const fallback = seedProfiles && seedProfiles.length > 0 ? seedProfiles : [];
      setUsers(fallback.length > 0 ? fallback : []);
    }
  }, [STORAGE_KEY, seedProfiles]);

  const persistUsers = (nextUsers: UserProfile[]) => {
    setUsers(nextUsers);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(nextUsers));
  };

  const handleAddUser = () => {
    const cleanName = newUserName.trim();
    if (cleanName) {
      const base = cleanName.toLowerCase().replace(/[^a-z0-9\u4e00-\u9fa5]/g, '');
      const newUserId = `user_${base || 'new'}_${Date.now()}`;
      const newUser: UserProfile = {
        id: newUserId,
        name: cleanName,
        avatar: '🙂'
      };
      const nextUsers = [...users, newUser];
      persistUsers(nextUsers);
      onNewUser(newUser);
      setNewUserName('');
      setShowNewUserForm(false);
    }
  };

  if (users.length === 0) {
    return (
      <div className="user-selector">
        <div className="user-selector-title">👤 用户选择</div>
        <p className="muted" style={{ padding: '8px', fontSize: 12 }}>
          正在载入用户列表…若长时间为空，请重新登录。
        </p>
      </div>
    );
  }

  return (
    <div className="user-selector">
      <div className="user-selector-title">👤 用户选择（本机）</div>
      <div className="user-list">
        {users.map((user) => (
          <div
            key={user.id}
            className={`user-item ${currentUserId === user.id ? 'active' : ''}`}
            onClick={() => onUserChange(user.id)}
          >
            <span className="user-avatar">{user.avatar}</span>
            <span className="user-name">{user.name}</span>
          </div>
        ))}
      </div>

      {!showNewUserForm ? (
        <button className="add-user-btn" onClick={() => setShowNewUserForm(true)}>
          + 添加咨询身份
        </button>
      ) : (
        <div className="new-user-form">
          <input
            type="text"
            value={newUserName}
            onChange={(e) => setNewUserName(e.target.value)}
            placeholder="输入称呼（如同桌 / 来访者别名）"
            className="new-user-input"
            autoFocus
          />
          <div className="new-user-actions">
            <button type="button" className="submit-btn" onClick={handleAddUser}>确定</button>
            <button type="button" className="cancel-btn" onClick={() => setShowNewUserForm(false)}>取消</button>
          </div>
        </div>
      )}
    </div>
  );
};
